"""Build an offline evidence gallery; no network dependencies or invented results."""
from pathlib import Path
import json, html
E=Path('docs/mission-26-2-evidence')
def read(p,default=None):
 f=E/p;return json.loads(f.read_text())if f.exists()else(default or {})
def esc(x):return html.escape(str(x))
def num(x):return '—'if x is None else f'{x:.2f}'
def a(p,label=None):return f'<a href="{esc(p)}">{esc(label or p)}</a>'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>'for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>'for x in row)+'</tr>'for row in rows)+'</tbody></table></div>'
accept=read('acceptance.json');journeys=read('journey-summary.json');perf=read('performance-summary.json');audio=read('audio-analysis.json')
parts=['''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>M26.2 · Dossier de vérité</title><style>
:root{color-scheme:dark;font:16px/1.6 system-ui;background:#0b1721;color:#e3edf1}body{margin:0}main{max-width:1180px;margin:auto;padding:24px}h1{font-size:2.4rem;line-height:1.15}h2{margin-top:3rem;color:#a7dfcc}h3{color:#ffcf79}a{color:#a4d4ff;text-underline-offset:3px}a:hover{color:white}nav{position:sticky;top:0;background:#14242ff5;padding:10px;display:flex;gap:12px;flex-wrap:wrap;z-index:5}nav a,button,summary{min-height:44px;display:inline-flex;align-items:center;padding:0 10px}button{background:#253e4e;color:white;border:1px solid #587281;border-radius:6px;cursor:pointer}header,.note{border-left:4px solid #ffbf47;padding:12px 20px;background:#1e2e37}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:20px}article{background:#132632;border:1px solid #344e5e;border-radius:10px;padding:16px;overflow:hidden}img,video{max-width:100%;height:auto;border-radius:6px}video{width:100%;background:#000}audio{max-width:100%}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.88rem}th,td{padding:10px;border:1px solid #3b5361;text-align:left;vertical-align:top}th{background:#203a49}.badge{font-weight:bold;color:#ffcf79}small{color:#bacdd6}code{word-break:break-all}.map{max-height:780px;overflow:auto;background:#101e28}.map svg{width:100%;height:auto;min-width:320px}footer{margin:50px 0;color:#b1c6d0}.good{color:#67e2a3}.bad{color:#ff8991}label{display:inline-flex;align-items:center;min-height:44px;gap:8px;margin-right:12px;padding:6px}details{margin:12px 0}p{max-width:90ch}</style>
<nav><a href="#verdict">Verdict</a><a href="#map">Carte</a><a href="#trips">Voyages</a><a href="#native">Films & son</a><a href="#perf">Performance</a><a href="#acceptance">22 scénarios</a><a href="#failures">Échecs</a><a href="REPRODUCTION.md">Reproduire</a></nav><main>
<header id="verdict"><small>ENDLESS EARTH · MISSION 26.2 · 16 NOVEMBRE 2026</small><h1>Des corrections réelles.<br>Une Vienne encore partiellement jouable.</h1><p class="badge">PARTIEL · PR 38 conservée en brouillon · Non prête à fusionner</p><p>La marche accélérée depuis Chauvigny atteint 12,97 km sur cinq tuiles. L’aller-retour sélectionné d’Angles réussit sur 2,377 km. La voiture atteint 3,88 km dans l’essai de vallée, puis refuse une discontinuité de hauteur. Aucun nouveau kilomètre de packraft n’est certifié.</p><p>Les clips ci-dessous sont natifs. Leur faible cadence SwiftShader reste visible et ne prouve pas la fluidité. Aucun test de GPU physique, de téléphone ni appréciation humaine de l’image ou du son n’est revendiqué.</p></header>''']
parts.append('<p>'+a('../mission-26-2.md','Rapport propriétaire')+' · '+a('../mission-26-2-architecture.md','Architecture')+' · '+a('../mission-26-2-data.md','Données et droits')+' · '+a('acceptance.json','Acceptance JSON')+' · '+a('artifact-manifest.json','Empreintes des artefacts')+'</p>')
parts.append('<h2 id="map">Carte de vérité du département</h2><p>Bleu gris : les 499 packs de données. Ambre : permissions candidates, sans surface entièrement praticable mesurée. Pointillés gris : plans de route. Vert : traces physiques réellement observées. Rouge : arrêts. Violet : secteurs aquatiques non validés. Brun : échantillons de restrictions ou accès inconnus des sources, sans trajet de contrôle. Aucune nouvelle tranche navigable n’est annoncée.</p><div id="map-controls">')
for kind,label in [('data-coverage','Couverture'),('permission-candidate','Permissions'),('source-plan','Plans'),('actual-controller-trip','Voyages'),('trip-stop','Arrêts')]:parts.append(f'<label><input type="checkbox" checked data-layer="{kind}">{label}</label>')
parts.append('</div><div class="map">'+(E/'truth-map.svg').read_text()+'</div><p>'+a('truth.geojson','GeoJSON WGS84 2D')+' · '+a('truth-map.svg','Carte exportable')+'</p>')
parts.append('<h2 id="trips">Voyages exécutés</h2><p>Contrôleur complet, collisions et entrées normales. Pas de réassignation de position pendant les trajets. Pas accéléré de 0,25 s, rendu aux checkpoints ; ces distances ne viennent ni du graphe ni d’un déplacement de caméra. Les placements hors Angles sont déclarés avant chaque essai indépendant.</p>')
parts.append(table(['Essai / source','Distance m','Temps mur / simulé s','Tuiles','Résultat'],[[a(c['file'],c['name'])+'<br><small>'+esc(c['sourceSHA'])+'</small>',num(c.get('distanceM')),num(c.get('wallSeconds'))+' / '+num(c.get('simulatedSeconds')),esc(', '.join(c['tiles'])),'terminé'if c['functionalSuccess']else'incomplet']for c in journeys.get('cases',[])]))
parts.append('<p class="note">À 12,97 km, le banc s’arrête sur sa garde de non-progression pendant une attente de préparation du support. Cela ne prouve pas une impossibilité géographique. La marche de 20 km reste non validée. Les Y anciens sont relatifs au pilote ; ce GeoJSON ne publie aucune altitude absolue inférée.</p>')
parts.append('<h2 id="native">Films natifs, images et mixage original</h2><p>640×420, DPR 1, graine 12345. Mixage stéréo du jeu, sans musique ajoutée. Originaux conservés, conteneurs indexés par copie codec, sans interpolation ni images ajoutées. Chaque film commence après une préparation de station déclarée ; seul « departure » garde le vrai spawn. Les distances et durées observées sont affichées, même en cas d’échec.</p>')
natives={label:read(label+'-native.json',{'cases':[]})for label in ['reference','candidate']}
for scene in ['run-flat-front','departure','forest-birds-shadows','pilot-boat']:
 parts.append('<h3>'+esc(scene)+'</h3><div class="grid">')
 for label in ['reference','candidate']:
  c=next((x for x in natives[label]['cases']if x['name']==scene),{})
  parts.append('<article><h4>'+('M26.1 · référence'if label=='reference'else'M26.2 · candidat')+'</h4><small>Source <code>'+esc(c.get('sourceSHA','non exécuté'))+'</code></small>')
  if c.get('video'):
   parts.append(f'<video controls playsinline preload="metadata" src="{esc(c["video"])}"></video>')
   parts.append('<p>'+num(c.get('observedWallSeconds'))+' s observées · '+num(c.get('averageRenderedFps'))+' FPS rendues · '+num(c.get('distanceM'))+' m physiques · course consécutive '+num(c.get('longestConsecutiveObservedRunS'))+' s murales.</p>')
   parts.append('<p>Horloge environnement : '+num(c.get('environmentClockElapsedS'))+' s · temps contrôleur exact non exporté ; borne supérieure '+num(c.get('controllerElapsedUpperBoundS'))+' s. '+a('native-timing-analysis.json','Méthode et correction')+'</p>')
   before=c.get('before',{});parts.append('<small>GPS initial : '+esc(before.get('gps'))+' · Profil : '+esc(before.get('profile',before.get('planet',{}).get('frame',{})))+' · Buffer : '+esc(before.get('buffer'))+'</small>')
   parts.append('<p>'+a(c['video'],'Film indexé')+' · '+a(c['original'],'Original natif')+' · '+a(c['framesFile'],'Frames')+' · '+a(c['transformsFile'],'Transformations')+'</p><audio controls preload="none" src="'+esc(c['video'])+'"></audio>')
  else:parts.append('<p class="bad">'+esc(c.get('failure','Film non produit'))+'</p>')
  parts.append('<p class="badge">'+('Capture valide'if c.get('captureValid')else'Capture non validée')+' · scénario complet non certifié</p><p>'+esc(c.get('acceptanceLimit',''))+'</p>')
  for suffix in ['before','after']:
   p=f'{label}-{scene}-{suffix}.png'
   if(E/p).exists():parts.append('<details><summary>'+('Avant'if suffix=='before'else'Après')+'</summary><img loading="lazy" src="'+p+'" alt="'+esc(label+' '+scene+' '+suffix)+'"></details>')
  parts.append('</article>')
 parts.append('</div>')
parts.append('<p>'+a('audio-analysis.json','Paquets audio, RMS, pics et stéréo')+' · '+a('licenses/audio-sources.json','Sources et licences audio')+'. Présence d’un signal ne vaut pas écoute humaine. Les stations initiales sont comparables ; les trajectoires peuvent diverger avec la cadence réelle.</p>')
parts.append('<h2 id="perf">Performance : les limites restent visibles</h2><p>Bancs sans encodeur, trois profils avec effets et audio actifs, framebuffer imposé identiquement. Machine distante sans /dev/dri, Chromium SwiftShader. Échantillons de 20 secondes : P99 incertain ; aucun résultat matériel 60/30 FPS ni borne de non-régression ≤5 % validé. Les cas sans mesure restent des échecs. Les matrices de caméra ne sont pas exportées dans ces snapshots ; la phase de chauffe et les trajectoires peuvent diverger.</p>')
parts.append(table(['Profil / scène','FPS réf.','FPS candidat','Variation %','P95 réf. ms','P95 cand. ms','Cas fonctionnels comparables'],[[esc(c['profile']+' / '+c['scene']),num(c.get('referenceFps')),num(c.get('candidateFps')),num(c.get('fpsChangePercent')),num(c.get('referenceP95Ms')),num(c.get('candidateP95Ms')),'oui'if c.get('matchedFunctionalCase')else'non']for c in perf.get('comparisons',[])]))
parts.append('<p>'+a('performance-summary.json','P50/P95/P99/max, mémoire et étapes de préparation')+' · '+a('reference-benchmarks.json','Mesures brutes référence')+' · '+a('candidate-benchmarks.json','Mesures brutes candidat')+'</p><p>96 MiB = géographie décodée résidente seulement. Heap, miroirs CPU et données décodées se recouvrent ; GPU/pilote, pics worker et allocations natives ne sont pas mesurés.</p>')
parts.append('<h2 id="acceptance">22 scénarios et cinq P0</h2>')
parts.append(table(['ID','Statut','Résultat / limite','Preuves'],[[esc(c['id']+' · '+c['title']),'<b>'+esc(c['status'])+'</b>',esc(c['reason']),' · '.join(a(p)for p in c['evidence'])]for c in accept.get('scenarios',[])]))
parts.append(table(['P0','Statut','Avant / après et limite'],[[esc(c['title']),esc(c['status']),esc(c['reason'])]for c in accept.get('historicalP0',[])]))
parts.append('<h2 id="failures">Échecs, versions et préservation</h2><p>'+a('residual-defects.json','Registre des défauts géolocalisés')+' · '+a('audit.json','Audit des données protégées')+' · '+a('baseline-inventory.json','Inventaire initial M26.1')+' · '+a('trial-logs.json','Index des journaux et essais intermédiaires')+' · '+a('../mission-26-1-evidence/index.html','Galerie historique M26.1 conservée')+'</p><details><summary>Toutes les tentatives conservées</summary><ul>')
for p in sorted((E/'failed-attempts').glob('*')):
 if p.is_file():parts.append('<li>'+a(str(p.relative_to(E)))+'</li>')
parts.append('</ul></details><div class="grid">')
for p,label in [('blockage-probe.png','Refus près de l’eau : Angles'),('Chauvigny-foot-21km-foot-stop.png','Arrêt de la marche multi-tuile'),('Vallee-car-40km-car-stop.png','Refus de hauteur automobile'),('area-42169715.png','Jardin Botanique : courte marche admise'),('fixture.png','Fixture synthétique hors France')]:
 if(E/p).exists():parts.append('<article><h3>'+label+'</h3><img loading="lazy" src="'+p+'" alt="'+label+'"></article>')
parts.append('</div><p>'+a('builds/reference-final/receipt.json','Build référence exact')+' · '+a('builds/candidate-final/receipt.json','Build candidat exact')+' · '+a('checks/tests.txt','437 tests')+' · '+a('checks/build.txt','Compilation')+' · '+a('gallery-check.json','Contrôles de la galerie')+'</p><footer>Un seul dossier consolidé, même PR brouillon 38. Aucun merge, déploiement ou achat. Sources IGN/OSM et licences historiques conservées. Données © contributeurs OpenStreetMap (ODbL) et IGN (Licence Ouverte 2.0), selon leurs manifestes. Aucun nouveau droit d’accès, profondeur mesurée ou trajet réussi inventé.</footer></main><script>document.querySelectorAll("[data-layer]").forEach(i=>i.addEventListener("change",()=>document.querySelectorAll(".map ."+i.dataset.layer).forEach(g=>g.style.display=i.checked?"":"none")));</script></html>')
(E/'index.html').write_text('\n'.join(parts))
